select case when temp_c >= 35.8 then 'PREMIUM' else 'STANDARD' end as temp_c_tier, count(*) as cnt, size(collect_set(device_code)) as num_device_codes, sum(humidity) filter (where device_code = 'DV-02') as dv_02_total_humidity, bit_and(status_bits) as status_bits_bit_and from device_readings group by case when temp_c >= 35.8 then 'PREMIUM' else 'STANDARD' end having bit_and(status_bits) < 1 order by temp_c_tier desc nulls first;
